def field(label,name,value='',kind='text',options=None,ro=False,help='',required=True):
 label=html.escape(label);v=html.escape(str(value),quote=True)
 attrs=f'id="{name}" name="{name}" '+('required ' if required else '')+('readonly class="readonly" ' if ro else '')
 if options is not None:control=f'<select {attrs}>'+''.join(f'<option>{html.escape(str(o))}</option>' for o in options)+'</select>'
 elif kind=='textarea':control=f'<textarea {attrs}>{v}</textarea>'
 else:control=f'<input {attrs} type="{kind}" value="{v}">'
 return f'<div class="field"><label for="{name}">{label} '+('<span class="required">*</span>' if required else '')+f'</label>{control}'+(f'<div class="help">{help}</div>' if help else '')+'</div>'
def badge(v):
 cls='green' if v in ['Activo','Activa','Aprobada','Al día','Completado'] else 'red' if v in ['Vencido','Rechazada','Inactivo','Inactiva','Rezagado'] else 'amber'
 return f'<span class="badge {cls}">{html.escape(v)}</span>'
def stats(items):return '<div class="stats">'+''.join(f'<div class="stat"><small>{a}</small><strong>{b}</strong><span>{c}</span></div>' for a,b,c in items)+'</div>'
def table(cols,rows,title='',action=False):
 tr=''.join('<tr>'+''.join(f'<td>{v}</td>' for v in r)+('<td><div class="actions"><button class="linkbtn" data-action="Ver">Ver</button><button class="linkbtn" data-action="Editar">Editar</button><button class="linkbtn" data-action="Desactivar">Desactivar</button></div></td>' if action else '')+'</tr>' for r in rows)
 return f'<div class="tablewrap"><table><thead><tr>'+''.join(f'<th>{c}</th>' for c in cols+(['Acciones'] if action else []))+'</tr></thead><tbody>'+tr+'</tbody></table></div>'
def pager():return '<div class="pager"><span id="count">Datos de ejemplo</span><div class="pagebuttons"><button class="btn small" id="prev">Anterior</button><button class="btn small primary" id="page">1</button><button class="btn small" id="next">Siguiente</button></div></div>'
def tools(placeholder='Buscar por código, nombre o descripción…'):return f'<div class="toolbar"><label for="search"><span>Buscar registros</span><input id="search" type="search" placeholder="{placeholder}"></label><label for="status" style="max-width:170px"><span>Estado</span><select id="status"><option>Todos</option><option>Activo</option><option>Inactivo</option></select></label><button class="btn soft" id="excel">↓ Exportar a Excel</button></div>'
def states():return '<div class="statebar"><small>Explorar estados del mockup:</small>'+''.join(f'<button class="btn small" data-state="{k}">{v}</button>' for k,v in [('list','Listado'),('loading','Cargando'),('empty','Sin registros'),('nomatch','Sin coincidencias'),('error','Error')])+'</div>'
def modal(fields):return '<dialog id="editor"><form id="editform"><div class="modalhead"><h2 id="modalTitle">Nuevo registro</h2><button type="button" class="linkbtn" onclick="editor.close()">Cerrar</button></div><div class="body grid">'+fields+'</div><div class="formfoot"><button type="button" class="btn" onclick="editor.close()">Cancelar</button><button class="btn primary" type="submit" id="saveedit">Guardar</button></div></form></dialog>'
