def catalog(i):
 name,cols,rows,fields=CATALOGS[i]
 fs=''.join(field(a,b,kind='email' if b=='correo' else 'text',options=['DEL01 · Las Compañías'] if b=='delegaciones' else ['Social','Territorial','Orientación'] if b=='tipo' else ['Administrador','Operador','Consultor'] if b=='rol' else ['Delegación asignada','Delegaciones autorizadas'] if b=='alcance' else None) for a,b in fields)
 fs+=field('Estado','estado',options=['Activo','Inactivo'])
 if i==15:fs+='<div class="field full"><label>Permisos autorizados *</label><p><label><input type="checkbox" checked> Consultar</label> <label><input type="checkbox"> Registrar</label> <label><input type="checkbox"> Administrar</label></p></div>'
 notice='Los registros relacionados no se eliminan sin revisar su uso. El perfil determina las acciones disponibles.'
 if i==19:notice='Cada subatención debe pertenecer a un Tipo de Atención activo. El cambio se valida antes de guardar.'
 content='<div class="notice neutral">'+notice+'</div><div class="card">'+tools()+ '<div id="results">'+table(cols,[[badge(v) if j==len(r)-1 else v for j,v in enumerate(r)] for r in rows],action=True)+'</div>'+pager()+states()+'</div>'+modal(fs)
 return content,'Catálogo y administración','Consulta, organiza y mantiene los registros del contexto autorizado.','<button class="btn primary" id="newrecord">+ Nuevo registro</button>'
def auth(i):
 titles={1:('Bienvenido al SGR','Ingresa con tus credenciales para continuar.'),11:('Recuperar contraseña','Solicita un código para restablecer tu acceso.'),12:('Verificar código','Ingresa los seis dígitos enviados a tu correo.'),13:('Crear nueva contraseña','Define una nueva clave después de verificar el código.')};title,sub=titles[i]
 fields='';step=''
 if i==1:
  fields=field('Usuario o correo','username',help='El rol y la delegación se obtienen de tu cuenta al ingresar.')+field('Contraseña','password',kind='password')+'<div style="text-align:right;margin:12px 0 24px"><a href="M-11_Recuperar_Contrasena.html">¿Olvidaste tu contraseña?</a></div>'
 elif i==11:fields=field('Correo asociado a tu cuenta','email',kind='email')+'<div class="notice neutral">Si el correo está asociado a una cuenta, recibirás las instrucciones. La respuesta no revela la existencia de otras cuentas.</div>'
 elif i==12:fields=field('Código de verificación','code',help='Puedes pegar el código completo. La vigencia y el reenvío dependen de la configuración.')+'<div class="help" style="display:flex;justify-content:space-between"><span>Ejemplo: vence en 10 minutos</span><button type="button" class="linkbtn" id="resend">Reenviar código</button></div>'
 elif i==13:fields=field('Nueva contraseña','newpass',kind='password')+field('Confirmar contraseña','confirmpass',kind='password')+'<div class="notice neutral">Reglas de ejemplo: al menos 8 caracteres, una mayúscula, una minúscula y un número. La política definitiva se configura para el proyecto.</div>'
 if i!=1:step='<div class="step">'+''.join(f'<span class="{"active" if j<=i-11 else ""}"></span>' for j in range(3))+'</div>'
 action={1:'Ingresar al sistema',11:'Enviar código',12:'Verificar código',13:'Guardar nueva contraseña'}[i]
 return f'<div class="authwrap"><section class="authintro"><div class="eyebrow">Sistema de Gestión de Resultados</div><h1>Una gestión municipal<br>más clara y conectada.</h1><p>Atenciones, compromisos y resultados en un mismo espacio de trabajo.</p><div style="margin-top:35px"><span class="badge">Proyecto académico · Datos ficticios</span></div></section><section class="authpanel"><div class="authcard"><div class="eyebrow">Acceso municipal</div><h1>{title}</h1><p class="sub">{sub}</p>{step}<form id="authform" data-auth="{i}">{fields}<button class="btn primary">{action} →</button></form><div class="authback"><a href="M-01_Login_Acceso.html">Volver al ingreso</a> · <a href="../index.html">Ver todas las pantallas</a></div><div class="footer">Prototipo académico. No autentica ni envía correos reales.</div></div></section></div>'
def attention():
 f=field('Solicitante','solicitante',help='Identifica al solicitante según el modelo del proyecto.')+field('Delegación de atención','delegacion','DEL01 · Las Compañías',ro=True,required=False,help='Asignada por el contexto autorizado.')+field('Tipo de Atención','tipo',options=['Seleccionar tipo','Social','Territorial','Orientación'])+field('Sub Atención','subtipo',options=['Seleccionar primero el tipo'])+'<div class="full">'+field('Descripción de la atención','descripcion',kind='textarea')+'</div><div class="full" id="socialcase" hidden><div class="notice neutral">Atención social: el caso conserva hasta tres gestiones diferenciadas del mismo solicitante.</div>'+field('Código del caso social (si corresponde)','casosocial',required=False,help='Vincula la gestión a un caso existente del mismo solicitante.')+'</div>'+field('Responsable','responsable','Usuario de ejemplo · Operador',ro=True,required=False)+field('Fecha y hora','fecha','Se asignan al guardar',ro=True,required=False)
 return '<div class="notice neutral">El tipo determina las subatenciones disponibles. Delegación, responsable y fecha se conservan con el registro.</div><div class="card"><div class="cardhead"><h2>Datos de la atención</h2><span class="badge">Campos obligatorios *</span></div><form id="attentionform"><div class="body grid">'+f+'</div><div class="formfoot"><button class="btn" type="button" id="cancelattention">Cancelar</button><button class="btn primary" id="saveattention">Guardar atención</button></div></form></div>', 'Atención ciudadana','Registra la solicitud y sus antecedentes en el contexto de tu delegación.',''
